)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE c.oid=ANY(ARRAY[to_regclass('procurement.sourcing_manual_contacts'),to_regclass('procurement.sourcing_manual_quote_versions'),to_regclass('procurement.supplier_bids'),to_regclass('procurement.supplier_bid_lines'),to_regclass('procurement.sourcing_invitations'),to_regclass('procurement.sourcing_publication_openings'),to_regclass('procurement.sourcing_publication_decisions')])
